# MoodiMOS — Assembly in Autodesk Fusion
# 
#  Launch: Utilities > Add-ons > Scripts and Add-ons > « + » (existing script)
#           > Select the MoodiMOS_Assembly folder > Run.
#  Imports pieces as generated by the parent folder’s Python scripts (`robot_parts.py`, `robot_limbs.py`): `../stl/*.stl`, in mm, already positioned in the torso reference frame (x to the right when viewed from the front, y toward the rear, z upward). No recalculations are performed here: Fusion displays exactly the pieces printed and rendered by Blender.
# 
#  One piece = one component (e.g., split into Head, Torso, Limbs, and « Render (non-printed) » (windows, coatings, BH1750 ball)).
#  Colors: From `robot_render.py` (read from this file, converted to sRGB) to ensure Fusion and Blender remain identical.
# 
#  Pieces are meshes (sculpted limb shapes): dimensions adjust in Python scripts, then re-run. To machine a piece in Fusion: right-click the mesh > Convert Mesh (simple head/torso pieces).
#  Before launch: Generate STL files (see `../README.md`).

import adsk.core, adsk.fusion, traceback, os, ast, unicodedata

HERE = os.path.dirname(os.path.realpath(__file__))
ROBOT_DIR = os.path.normpath(os.path.join(HERE, ".."))
STL_DIR = os.path.join(ROBOT_DIR, "stl")

GROUPS = (('Head', ("head_",)), ('Torso', ("torso_",)),
          ('Render (non-printed)', ("glass_", "paint_", "component_")))
DEFAULT_GROUP = "Limbs"


def read_render_colors():
    'COL, PIECE_COL, and GLOW from `robot_render.py` (Python literals), without running Blender.'
    tree = ast.parse(open(os.path.join(ROBOT_DIR, "robot_render.py"), encoding="utf-8").read())
    found = {}
    for node in tree.body:
        if isinstance(node, ast.Assign) and getattr(node.targets[0], "id", "") in ("COL", "PIECE_COL", "GLOW"):
            found[node.targets[0].id] = ast.literal_eval(node.value)
    return found.get("COL", {}), found.get("PIECE_COL", {}), found.get("GLOW", ())


def srgb(c):
    'Linear color (Blender) → 0-255 sRGB (Fusion).'
    c = max(0.0, min(1.0, c))
    v = 12.92 * c if c <= 0.0031308 else 1.055 * c ** (1 / 2.4) - 0.055
    return int(round(v * 255))


def nfc(s):
    return unicodedata.normalize("NFC", s)   # macOS filenames (composed accents)


def color_key(stem, piece_col, glow):
    if stem.startswith(glow):
        return "glow"
    if stem.startswith("glass"):
        return "glass"
    for k in sorted(piece_col, key=len, reverse=True):
        if stem == k or stem.startswith(k + "_"):
            return piece_col[k]
    return "white"


# Component names: (name, gender) for agreement with « right/right »; otherwise, name extracted from the file.
NAMES = {
    "head_bezel": ("Bezel", "f"), "head_plate": ('Drop Plate', "f"), "head_back": ('Dome', "m"),
    "paint_bail": ('Painted Bearing', "f"), "paint_medallion": ('Painted medallion', "m"),
    'paint_trim_bezel': ('Painted bezel of the lens', "m"),
    "paint_strip_headphone": ("Strip peint du headphone", "m"),
    "torso_body": ('Torso body', "m"), "torso_front": ('Torso front panel', "f"), "torso_back": ('Torso back panel', "m"),
    "torso_frame": ('Screen frame', "m"),
    "torso_speaker_box": ('Speaker enclosure', "f"), "torso_strip": ('Luminescent bezel', "m"),
    "glass_head": ('Head glass', "f"), "glass_torso": ('Torso glass', "f"),
    "paint_marks": ("Index peints de la bezel", "mp"), "paint_screws": ('Painted head bolt heads', "fp"),
    "component_bh1750": ("Boule du BH1750", "f"),
    "shoulder": ("Shoulder", "f"), "arm": ("Arm", "m"), "ring_arm": ("Ring de coude", "f"),
    "cuff": ("Bracelet", "m"), "glove": ("Poing", "m"), "trim_glove": ('Finger rings', "mp"),
    'wrist_glove': ('Ring de wrist', "f"),
    "leg": ("Leg", "f"), "ring_leg": ("Bagues de leg", "fp"),
    "trim": ("Semelle noire", "f"), 'sole': ("Intercalaire", "m"), 'toe': ("Bout", "m"),
    'upper': ("Empeigne", "f"), 'side': ('Rear panel', "m"), 'heel': ("Talon", "m"),
    'collar': ("Collerette", "f"), 'laces': ("Bride", "f"), 'roundel': ("Anneau lumineux", "m"),
    "vent_sneaker": ('Sneaker vents', "fp"), 'edge_toe': ('Trait du toe', "m"),
}
SIDE = {("right", "m"): "right", ("right", "f"): "right", ("right", "mp"): "droits", ("right", "fp"): "droites",
        ("left", "m"): "left", ("left", "f"): "left", ("left", "mp"): "gauches", ("left", "fp"): "gauches"}


def label(stem):
    '« arm_right » → « Right arm », « arm_left » → « Left arm », « shoulder_right » → « Right shoulder »'
    kind, side = stem, None
    for sd in ("right", "left"):
        if stem.endswith("_" + sd):
            kind, side = stem[: -len(sd) - 1], sd
    name, g = NAMES.get(kind, (kind.replace("_", " ").capitalize(), "m"))
    return name if side is None else "{} {}".format(name, SIDE[(side, g)])


def group_of(stem):
    for name, prefixes in GROUPS:
        if stem.startswith(prefixes):
            return name
    return DEFAULT_GROUP


def base_appearance(app):
    for lib in app.materialLibraries:
        try:
            aps = lib.appearances
        except Exception:
            continue
        for i in range(aps.count):
            if "Plastic" in aps.item(i).name or "Plastique" in aps.item(i).name:
                return aps.item(i)
    return None


def make_appearances(app, design, col):
    base = base_appearance(app)
    if base is None:
        return {}
    rgb = {k: tuple(srgb(c) for c in v[0]) for k, v in col.items()}
    rgb["glow"] = (255, 110, 20)       # Finger rings and luminous trim
    rgb["glass"] = (12, 12, 14)        # Screen glass panels
    made = {}
    for key, (r, g, b) in rgb.items():
        name = "MoodiMOS " + key
        ap = design.appearances.itemByName(name) or design.appearances.addByCopy(base, name)
        for prop in ap.appearanceProperties:
            if prop.objectType == adsk.core.ColorProperty.classType():
                try:
                    prop.value = adsk.core.Color.create(r, g, b, 255)
                except Exception:
                    pass
        made[key] = ap
    return made


def run(context):
    ui = None
    try:
        app = adsk.core.Application.get()
        ui = app.userInterface
        if not os.path.isdir(STL_DIR):
            ui.messageBox('Missing folder:\n{}\n\nGenerate STL files first (robot_parts.py, robot_limbs.py).'.format(STL_DIR))
            return
        files = sorted(f for f in os.listdir(STL_DIR) if f.lower().endswith(".stl"))
        if not files:
            ui.messageBox('No STL files found in {}. Generate pieces first (see README.md).'.format(STL_DIR))
            return

        app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
        design = adsk.fusion.Design.cast(app.activeProduct)
        design.designType = adsk.fusion.DesignTypes.ParametricDesignType
        root = design.rootComponent
        col, piece_col, glow = read_render_colors()
        appearances = make_appearances(app, design, col)

        identity = adsk.core.Matrix3D.create()
        groups = {}
        imported, errors = 0, []
        progress = ui.createProgressDialog()
        progress.show("MoodiMOS", "Import des pièces : %v / %m", 0, len(files), 0)
        for i, f in enumerate(files):
            stem = nfc(f[:-4])
            progress.progressValue = i
            if progress.wasCancelled:
                break
            try:
                gname = group_of(stem)
                if gname not in groups:
                    occ_g = root.occurrences.addNewComponent(identity)
                    occ_g.component.name = gname
                    groups[gname] = occ_g.component
                occ = groups[gname].occurrences.addNewComponent(identity)
                comp = occ.component
                comp.name = label(stem)
                base = comp.features.baseFeatures.add()
                base.startEdit()
                try:
                    bodies = comp.meshBodies.add(os.path.join(STL_DIR, f), adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
                finally:
                    base.finishEdit()
                ap = appearances.get(color_key(stem, piece_col, glow))
                for k in range(bodies.count):
                    bodies.item(k).name = stem
                    if ap:
                        try:
                            bodies.item(k).appearance = ap
                        except Exception:
                            pass
                if ap:
                    try:
                        occ.appearance = ap
                    except Exception:
                        pass
                imported += 1
            except Exception as e:
                errors.append("{} : {}".format(f, e))
        progress.hide()
        app.activeViewport.fit()
        msg = 'MoodiMOS: {} piece(s) imported from\n{}\n\nGroups: {}.'.format(
            imported, STL_DIR, ", ".join(sorted(groups)))
        if not appearances:
            msg += 'No plastic aspect found: colors not applied.'
        if errors:
            msg += '{} error(s), e.g.:\n{}'.format(len(errors), "\n".join(errors[:5]))
        ui.messageBox(msg)
    except Exception:
        if ui:
            ui.messageBox('Error:\n{}'.format(traceback.format_exc()))
